func solveNQueens(_ n: Int) -> [[String]] {
    var cols = Set<Int>(), d1 = Set<Int>(), d2 = Set<Int>()
    var placement = [Int](repeating: 0, count: n), result: [[String]] = []
    func place(_ r: Int) {
        if r == n {
            result.append(placement.map { c in String((0..<n).map { $0 == c ? "Q" : "." }) })
            return
        }
        for c in 0..<n where !cols.contains(c) && !d1.contains(r - c) && !d2.contains(r + c) {
            cols.insert(c); d1.insert(r - c); d2.insert(r + c); placement[r] = c
            place(r + 1)
            cols.remove(c); d1.remove(r - c); d2.remove(r + c)
        }
    }
    place(0)
    return result
}
